    private void btnLogin1ActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnLogin1ActionPerformed
        String nombre = txtUsuario.getText().trim();
String password = txtPassword.getText().trim();

try {
    Connection con = conexion.conectar();

    String sql = "SELECT c.CLI_id, c.CLI_nombre " +
                 "FROM CLIENTE c " +
                 "JOIN USUARIO u ON c.CLI_id = u.CLIENTE_CLI_id " +
                 "WHERE u.USU_nombre = ? AND u.USU_password = ?";

    PreparedStatement ps = con.prepareStatement(sql);
    ps.setString(1, nombre);
    ps.setString(2, password);

    ResultSet rs = ps.executeQuery();

    if (rs.next()) {
        int clienteId = rs.getInt("CLI_id");
        String nombreBD = rs.getString("CLI_nombre");
        javax.swing.JOptionPane.showMessageDialog(this, "Login correcto");

        JOptionPane.showMessageDialog(this, "Bienvenido " + nombreBD);

        Facial f = new Facial(clienteId);
        f.setVisible(true);
        this.dispose();
    } else {
        JOptionPane.showMessageDialog(this, "Nombre y contraseña incorrectas");
    }

} catch (Exception e) {
    JOptionPane.showMessageDialog(this, "Error: " + e.getMessage());
}
    }//GEN-LAST:event_btnLogin1ActionPerformed

    private void jButton1ActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_jButton1ActionPerformed
        // Dentro del evento del botón Registrar en LoginPrincipal
    RegistroUsuario ventana = new RegistroUsuario();
    ventana.setVisible(true); // Hace aparecer la ventana de registro
    this.dispose(); // Cierra el login actual
    }//GEN-LAST:event_jButton1ActionPerformed

